INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q612286', 'Fall of Nineveh', 'The Fall of Nineveh, also called the Battle of Nineveh, was a major battle that marked the climax of the Conquest of the Assyrian Empire in 612 BC. After the Assyrian defeat at the Fall of Assur, an allied army which involved the combined forces of Medes and the Babylonians besieged Nineveh (in modern-day Mosul) and took what was, at that time, one of the greatest cities in the world. The fall of Nineveh led to the destruction of the Neo-Assyrian Empire as the dominant state in the Ancient Near East over the following three years.', -612, NULL, NULL, NULL, NULL, NULL, 'year', '612 BCE', 61, 'https://en.wikipedia.org/wiki/Fall_of_Nineveh'),
  ('Q3434300', 'Battle of Opis', 'The Battle of Opis was the last major military engagement between the Achaemenid Empire and the Neo-Babylonian Empire, which took place in September 539 BC, during the Persian invasion of Mesopotamia. At the time, Babylonia was the last major power in Western Asia that was not yet under Persian control.', -539, 9, NULL, NULL, NULL, NULL, 'month', 'September 539 BCE', 53, 'https://en.wikipedia.org/wiki/Battle_of_Opis'),
  ('Q28169617', 'Fall of Babylon', 'The fall of Babylon occurred in 539 BCE, when the Achaemenid Empire conquered the Neo-Babylonian Empire. The success of the Persian campaign, led by Cyrus the Great, brought an end to the reign of the last native dynasty of Mesopotamia and gave the Persians control over the rest of the Fertile Crescent.', -539, NULL, NULL, NULL, NULL, NULL, 'year', '539 BCE', 58, 'https://en.wikipedia.org/wiki/Fall_of_Babylon'),
  ('Q431205', 'Battle of Cunaxa', 'The Battle of Cunaxa was fought in the late summer of 401 BC between the Persian king Artaxerxes II and his brother Cyrus the Younger for control of the Achaemenid throne. The great battle of the revolt of Cyrus took place 70 km north of Babylon, at Cunaxa (Greek: Κούναξα), on the left bank of the Euphrates.', -401, NULL, NULL, NULL, NULL, NULL, 'year', '401 BCE', 66, 'https://en.wikipedia.org/wiki/Battle_of_Cunaxa'),
  ('Q179670', 'Battle of Gaugamela', 'The Battle of Gaugamela ( GAW-gə-MEE-lə; Ancient Greek: Γαυγάμηλα, romanized: Gaugámēla, lit. ''the Camel''s House''), also called the Battle of Arbela (Ἄρβηλα, Árbēla), took place in 331 BC between the forces of the Army of Macedon under Alexander the Great and the Persian Army under King Darius III. It was the second and final battle between the two kings, and is considered to be the final blow to the Achaemenid Empire, resulting in its complete conquest by Alexander. The fighting took place in Gaugamela, a village on the banks of the river Bumodus, north of Arbela (modern-day Erbil, in…', -331, 10, 1, NULL, NULL, NULL, 'day', '1 October 331 BCE', 79, 'https://en.wikipedia.org/wiki/Battle_of_Gaugamela'),
  ('Q797952', 'Babylonian War', 'The Babylonian War was a conflict fought between 311–309 BC between Antigonus I Monophthalmus and Seleucus I Nicator, ending in a victory for Seleucus. This conflict ended any possibility of restoration of the former empire of Alexander the Great, a result confirmed in the Battle of Ipsus.', -311, NULL, NULL, -309, NULL, NULL, 'year', '311 BCE – 309 BCE', 52, 'https://en.wikipedia.org/wiki/Babylonian_War'),
  ('Q1583991', 'Battle of Misiche', 'The Battle of Misiche (Greek: Μισιχή), Mesiche, or Massice (Middle Persian: 𐭬𐭱‎𐭩‎𐭪‎‎‎‎ mšyk; Parthian: 𐭌‎𐭔‎𐭉‎𐭊‎ mšyk) (dated between January 13 and March 14, 244 AD) was fought between the Sasanians and the Romans in Misiche, Mesopotamia.', 244, NULL, NULL, NULL, NULL, NULL, 'year', '244', 52, 'https://en.wikipedia.org/wiki/Battle_of_Misiche'),
  ('Q767124', 'Battle of Ctesiphon', 'The Battle of Ctesiphon took place on 29 May 363 between the armies of Roman Emperor Julian and an army of the Sasanian Empire (during Shapur II''s reign) outside the walls of the Persian capital Ctesiphon. The battle resulted in a Roman victory, but eventually the Roman forces found themselves unable to continue their campaign as they were too far from their supply lines.', 363, 5, 29, NULL, NULL, NULL, 'day', '29 May 363', 55, 'https://en.wikipedia.org/wiki/Battle_of_Ctesiphon_(363)'),
  ('Q1231697', 'Battle of Samarra', 'The Battle of Samarra took place in June 363, during the invasion of the Sasanian Empire by the Roman emperor Julian. After marching his army to the gates of Ctesiphon and failing to take the city, Julian, realizing his army was low on provisions and in enemy territory, started marching towards Samarra.', 363, 6, NULL, NULL, NULL, NULL, 'month', 'June 363', 58, 'https://en.wikipedia.org/wiki/Battle_of_Samarra_(363)'),
  ('Q755966', 'Battle of Nineveh', 'The Battle of Nineveh was the climactic battle of the Byzantine–Sasanian War of 602–628. In mid-September 627, Heraclius invaded Sasanian Mesopotamia in a surprising, risky winter campaign.', 627, 12, 12, NULL, NULL, NULL, 'day', '12 December 627', 68, 'https://en.wikipedia.org/wiki/Battle_of_Nineveh_(627)'),
  ('Q2570386', 'Battle of al-Anbar', 'The Battle of Al-Anbar (Arabic: معركة الأنبار) was between the Muslim Arab army under the command of Khalid ibn al-Walid and the Sasanian Empire. The battle took place at Anbar which is located approximately 80 miles from the ancient city of Babylon.', 633, NULL, NULL, NULL, NULL, NULL, 'year', '633', 55, 'https://en.wikipedia.org/wiki/Battle_of_al-Anbar'),
  ('Q2576269', 'Battle of Ayn al-Tamr', 'The Battle of Ayn al-Tamr (Arabic: معركة عين التمر) took place in modern-day Iraq (Mesopotamia) between the early Muslim Arab forces and the Sassanians along with their Arab Christian auxiliary forces. Ayn al-Tamr is located west of Anbar and was a frontier post which had been established to aid the Sassanids.', 633, NULL, NULL, NULL, NULL, NULL, 'year', '633', 51, 'https://en.wikipedia.org/wiki/Battle_of_Ayn_al-Tamr'),
  ('Q2599625', 'Battle of Hira', 'The Battle of Hira (Arabic: معركة الحيرة) was fought between the Sasanian Empire and the Rashidun Caliphate in 633. It was one of the early battles of the Muslim conquest of Persia.', 633, 5, NULL, NULL, NULL, NULL, 'month', 'May 633', 57, 'https://en.wikipedia.org/wiki/Battle_of_Hira'),
  ('Q738132', 'Battle of Firaz', 'The Battle of Firaz (Arabic: مَعْرَكَة الْفِرَاض) also known as Battle of Firad, took place around January 634 between the Rashidun Caliphate and, reportedly, a combined force from the Byzantine Empire and Sasanian Empire.', 634, 1, NULL, NULL, NULL, NULL, 'month', 'January 634', 60, 'https://en.wikipedia.org/wiki/Battle_of_Firaz'),
  ('Q2067496', 'Battle of the Bridge', 'The Battle of the Bridge or the Battle of al-Jisr (Arabic: معركة الجسر) was fought at the bank of the Euphrates between Arab Muslims, led by Abu Ubayd al-Thaqafi, and the Persian Sasanians, led by Bahman Jaduya. It is traditionally dated to the year 634 and was the only major Sasanian victory over the invading Rashidun Caliphate army.', 634, 10, 22, NULL, NULL, NULL, 'day', '22 October 634', 60, 'https://en.wikipedia.org/wiki/Battle_of_the_Bridge'),
  ('Q836844', 'Battle of al-Qadisiyyah', 'The Battle of al-Qadisiyyah (Arabic: مَعْرَكَة ٱلْقَادِسِيَّة, romanized: Maʿrakat al-Qādisīya; Persian: نبرد قادسیه, romanized: Nabard-i Qādisiya) took place between the armies of the Rashidun Caliphate and the Sasanian Empire in November 636. It resulted in a decisive victory for the Rashidun army and is considered to be one of the most significant engagements of the Muslim conquest of Persia, and thereby of the early Muslim conquests as a whole.', 636, 11, 16, 636, 11, 19, 'day', '16 November 636 – 19 November 636', 71, 'https://en.wikipedia.org/wiki/Battle_of_al-Qadisiyyah'),
  ('Q1133574', 'Battle of the Camel', 'The Battle of the Camel, also known as the Battle of Basra (Arabic: معركة الجمل, romanized: Maʿrakat al-Jamal), took place in 656 CE outside of Basra in Iraq. It was fought between the partisans of the fourth Rashidun caliph Ali and the Uthmaniyya led by Aisha, Talha, and Zubayr.', 656, 11, 7, NULL, NULL, NULL, 'day', '7 November 656', 71, 'https://en.wikipedia.org/wiki/Battle_of_the_Camel'),
  ('Q626058', 'Battle of Karbala', 'The Battle of Karbala (Arabic: مَعْرَكَة كَرْبَلَاء, romanized: Maʿrakat Karbalāʾ) was fought on 10 October 680 (10 Muharram in the year 61 AH of the Islamic calendar) between the forces of the second Umayyad caliph Yazid I (r. 680–683), and a small army led by Husayn ibn Ali, second son of Ali and grandson of the Islamic prophet Muhammad, at Karbala, in modern-day southern Iraq. Prior to his death, the Umayyad caliph Mu''awiya I (r. 661–680) appointed his son Yazid as his successor, making the caliphate hereditary.', 680, 10, 10, NULL, NULL, NULL, 'day', '10 October 680', 78, 'https://en.wikipedia.org/wiki/Battle_of_Karbala'),
  ('Q3636337', 'Alid revolt of 762–763', 'The Alid revolt of 762–763 or Revolt of Muhammad the Pure Soul was an uprising by the Hasanid branch of the Alids against the newly established Abbasid Caliphate. The Hasanids, led by the brothers Muhammad (called "the Pure Soul") and Ibrahim, rejected the legitimacy of the Abbasid family''s claim to power.', 762, 9, NULL, 763, 2, NULL, 'month', 'September 762 – February 763', 51, 'https://en.wikipedia.org/wiki/Alid_revolt_of_762%E2%80%93763'),
  ('Q5036982', 'Capture of Baghdad', 'The 1534 capture of Baghdad by the Ottoman Sultan Suleiman the Magnificent from the Safavid Shah Tahmasp I was part of his Campaign of the Two Iraqs during the Ottoman–Safavid War (1532–1555). The city was taken without resistance, the Safavid government having fled and leaving the city undefended.', 1534, 12, NULL, NULL, NULL, NULL, 'month', 'December 1534', 51, 'https://en.wikipedia.org/wiki/Capture_of_Baghdad_(1534)'),
  ('Q5036981', 'Capture of Baghdad (1638)', 'The siege of Baghdad (Persian: محاصره بغداد) in the winter of 1638 marked the re-establishment of Ottoman control over Iraq, following a prior period of Safavid rule. It was part of the Ottoman–Safavid War of 1623–1639.', 1638, 11, 15, 1638, 12, 25, 'day', '15 November 1638 – 25 December 1638', 51, 'https://en.wikipedia.org/wiki/Siege_of_Baghdad_(1638)'),
  ('Q132555025', 'Siege of Baghdad', 'The Ottoman–Persian War of 1820–1823 was fought between the Ottoman Empire and Qajar Iran from 1820 to 1823.', 1821, NULL, NULL, NULL, NULL, NULL, 'year', '1821', 55, 'https://en.wikipedia.org/wiki/Siege_of_Baghdad_(1821)'),
  ('Q1327145', 'Battle of Basra', 'The Battle of Basra was a battle of World War I which took place south of the city of Basra, in Ottoman Iraq, between British and Ottoman troops from November 11 to November 22, 1914. The battle resulted in the British capture of Basra.', 1914, 11, 11, 1914, 11, 22, 'day', '11 November 1914 – 22 November 1914', 52, 'https://en.wikipedia.org/wiki/Battle_of_Basra_(1914)'),
  ('Q815166', 'Siege of Kut', 'The siege of Kut Al Amara (7 December 1915 – 29 April 1916), also known as the first battle of Kut, was the besieging of an 8,000-strong British Indian Army garrison in the town of Kut, 160 km (100 mi) south of Baghdad, by the Ottoman Army. In 1915, its population was around 6,500.', 1915, 12, 7, 1916, 4, 29, 'day', '7 December 1915 – 29 April 1916', 64, 'https://en.wikipedia.org/wiki/Siege_of_Kut'),
  ('Q1481878', 'Simele massacre', 'The Simele massacre (Syriac: ܦܪܲܡܬܵܐ ܕܣܸܡܹܠܹܐ, romanized: Premta d''Simele, Arabic: مذبحة سميل, romanized: maḏbaḥat Simīl), also known as the Assyrian affair, was a massacre committed by the Kingdom of Iraq under the leadership of Kurdish army general Bakr Sidqi. The massacre was committed in August 1933 against the Assyrian population of Iraq in and around the village of Simele.', 1933, 8, NULL, 1933, 8, 11, 'month', 'August 1933 – 11 August 1933', 61, 'https://en.wikipedia.org/wiki/Simele_massacre'),
  ('Q1765847', 'Attack on H3', 'The H-3 airstrike (Persian: عملیات اچ۳) was a surprise air attack by the Iranian Air Force during the Iran–Iraq War on 4 April 1981 against the Iraqi Air Force''s H-3 Air Base in western Iraq. The Iranians destroyed at least 48 Iraqi aircraft on the ground with no losses of their own.', 1981, 4, 4, NULL, NULL, NULL, 'day', '4 April 1981', 51, 'https://en.wikipedia.org/wiki/H-3_airstrike'),
  ('Q529723', 'Anfal campaign', 'The Anfal campaign,, also known as the Kurdish genocide was a counterinsurgency operation, described by many scholars and human rights groups as a genocide or ethnic cleansing, which was carried out by Ba''athist Iraq from February to September 1988 during the Iraqi–Kurdish conflict at the end of the Iran–Iraq War. The campaign targeted rural Kurds because its purpose was to eliminate Kurdish rebel groups and Arabize strategic parts of the Kirkuk Governorate.', 1988, 9, NULL, 1989, NULL, NULL, 'month', 'September 1988 – 1989', 70, 'https://en.wikipedia.org/wiki/Anfal_campaign'),
  ('Q760002', '1991 Iraqi uprisings', 'The 1991 Iraqi uprisings were ethnic and religious uprisings against Saddam Hussein''s Ba''athist regime that were mainly led by Shia and Kurdish rebels. The uprisings lasted from March to April 1991 after a ceasefire following the end of the Gulf War.', 1991, NULL, NULL, NULL, NULL, NULL, 'year', '1991', 58, 'https://en.wikipedia.org/wiki/1991_Iraqi_uprisings'),
  ('Q1154912', 'Iraqi Kurdish Civil War', 'The Iraqi Kurdish Civil War (Kurdish: شەڕی براکوژی, romanized: Şerî birakujî, lit. ''fratricidal war'') was a civil war that took place between rival Kurdish factions in Iraqi Kurdistan during the mid-1990s, mostly between the Patriotic Union of Kurdistan and the Kurdistan Democratic Party. Over the course of the conflict, Kurdish factions from Iran and Turkey, as well as Iranian, Iraqi and Turkish forces, were drawn into the fighting, with additional involvement from American forces.', 1994, 5, NULL, 1997, 11, 24, 'month', 'May 1994 – 24 November 1997', 51, 'https://en.wikipedia.org/wiki/Iraqi_Kurdish_Civil_War'),
  ('Q107802', '2003 invasion of Iraq', 'The 2003 invasion of Iraq was the first stage of the Iraq War. The invasion began on 20 March 2003 and lasted just over one month, including 26 days of major combat operations.', 2003, 3, 20, 2003, 5, 1, 'day', '20 March 2003 – 1 May 2003', 74, 'https://en.wikipedia.org/wiki/2003_invasion_of_Iraq'),
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q718851', 'Battle of Nasiriyah', 'The Battle of Nasiriyah was fought between the US 2nd Marine Expeditionary Brigade and Iraqi forces from 23 March to 2 April 2003 during the US-led invasion of Iraq. On the night of 24–25 March, the bulk of the Marines of Regimental Combat Team 1 passed through the city over the bridges and attacked north towards Baghdad.', 2003, 3, 23, 2003, 3, 29, 'day', '23 March 2003 – 29 March 2003', 56, 'https://en.wikipedia.org/wiki/Battle_of_Nasiriyah'),
  ('Q1804983', 'Battle of Baghdad', 'The Battle of Baghdad (Arabic: مَعْرَكَةُ بَغْدَاد, romanized: Maʿrakatu baghdād), also known as the Fall of Baghdad (Arabic: سُقُوطُ بَغْدَاد, romanized: suqūṭu baghdād), was a military engagement that took place in Baghdad in early April 2003, as part of the invasion of Iraq. Three weeks into the invasion of Iraq, Coalition Forces Land Component Command elements, led by the U.S. Army 3rd Infantry Division, captured Baghdad.', 2003, NULL, NULL, 2003, 4, 12, 'year', '2003', 57, 'https://en.wikipedia.org/wiki/Battle_of_Baghdad_(2003)'),
  ('Q2237268', 'Battle of Umm Qasr', 'The Battle of Umm Qasr was the first military confrontation in the Iraq War. At the start of the war, one of the first objectives was the port of Umm Qasr.', 2003, 3, 21, 2003, 3, 25, 'day', '21 March 2003 – 25 March 2003', 56, 'https://en.wikipedia.org/wiki/Battle_of_Umm_Qasr'),
  ('Q2585300', 'Battle of Basra', 'The Battle of Basra lasted from 21 March to 6 April 2003 and was one of the first battles of the 2003 invasion of Iraq. The British 7 Armoured Brigade fought their way into Iraq''s second-largest city, Basra, on 6 April coming under constant attack by the Iraqi Army 51st Division and Fedayeen Saddam, while elements of the British Parachute Regiment cleared the ''old quarter'' of the city that was inaccessible to vehicles.', 2003, 3, 21, 2003, 4, 6, 'day', '21 March 2003 – 6 April 2003', 57, 'https://en.wikipedia.org/wiki/Battle_of_Basra_(2003)'),
  ('Q47015896', 'Iraqi conflict', 'The Iraqi conflict is a series of violent events that began with the 2003 American-led invasion of Iraq and deposition of Iraqi dictator Saddam Hussein, followed by a series of conflicts including the protracted Iraq War (2003–2011), the Iraqi insurgency (2011–2013), the War in Iraq (2013–2017), and most recently, the small-scale Islamic State insurgency in 4 provinces located in Northern Iraq since 2017. In the ensuing 2003–2011 Iraq War, the Multi-National Force (MNF–I) led by the United States helped to establish a Shia-dominated federal government, which was soon opposed by an Iraqi…', 2003, 3, 20, 2017, 12, 9, 'day', '20 March 2003 – 9 December 2017', 52, 'https://en.wikipedia.org/wiki/Iraqi_conflict'),
  ('Q1330136', 'Second Battle of Fallujah', 'The Second Battle of Fallujah, initially codenamed Operation Phantom Fury, Operation al-Fajr (Arabic: الفجر, lit. ''The Dawn'') was an American-led offensive of the Iraq War that began on 7 November 2004 and lasted about six weeks. A joint military effort of the United States, the Iraqi Interim Government, and the United Kingdom, the battle was the war''s first major engagement fought solely against the Iraqi insurgency, not the military forces of the Ba''athist Iraq government.', 2004, 12, 23, 2004, 12, 23, 'day', '23 December 2004', 61, 'https://en.wikipedia.org/wiki/Second_Battle_of_Fallujah'),
  ('Q1537159', 'First Battle of Fallujah', 'The First Battle of Fallujah, code-named Operation Vigilant Resolve, was an American-led operation of the Iraq War against militants in Fallujah as well as an attempt to apprehend or kill the perpetrators of the killing of four U.S. contractors in March 2004. The chief catalyst for the operation was the highly publicized killing and mutilation of four Blackwater USA private military contractors, and the killings of five American soldiers in Habbaniyah a few days earlier.', 2004, 4, 4, 2004, 5, 1, 'day', '4 April 2004 – 1 May 2004', 61, 'https://en.wikipedia.org/wiki/First_Battle_of_Fallujah'),
  ('Q2889462', 'Battle of Najaf', 'The Battle of Najaf a battle during the Iraq War between United States-Iraqi government forces and the Shia insurgent Mahdi Army led by Muqtada al-Sadr in the Iraqi city of Najaf in April 2004 and conflict began again in August 2004.', 2004, NULL, NULL, 2004, 8, 27, 'year', '2004', 51, 'https://en.wikipedia.org/wiki/Battle_of_Najaf_(2004)'),
  ('Q981327', 'Haditha massacre', 'The Haditha massacre was a series of killings on November 19, 2005, in which a group of United States Marines killed 25 unarmed Iraqi civilians. It occurred in the city of Haditha in Iraq''s western province of Al Anbar.', 2005, 11, 19, NULL, NULL, NULL, 'day', '19 November 2005', 60, 'https://en.wikipedia.org/wiki/Haditha_massacre'),
  ('Q1018682', 'Nisour Square massacre', 'The Nisour Square massacre occurred on September 16, 2007, when employees of Blackwater Security Consulting (now Constellis), which was a private military company contracted by the United States government to provide security services in Iraq, shot at Iraqi civilians, killing 17 and injuring 20 in Nisour Square, Baghdad, while escorting a U.S. embassy convoy. The killings outraged Iraqis and strained relations between Iraq and the United States.', 2007, 9, 16, NULL, NULL, NULL, 'day', '16 September 2007', 52, 'https://en.wikipedia.org/wiki/Nisour_Square_massacre'),
  ('Q1149030', '2011 Iraqi protests', 'The 2011 Iraqi protests came in the wake of the Tunisian revolution and 2011 Egyptian revolution. They resulted in at least 35 deaths, including at least 29 on 25 February 2011, the "Day of Rage".', 2011, NULL, NULL, NULL, NULL, NULL, 'year', '2011', 52, 'https://en.wikipedia.org/wiki/2011_Iraqi_protests'),
  ('Q15553019', 'Anbar clashes (2013–2014)', 'Beginning in December 2012, Sunnis in Iraq protested against the Maliki government. On 28 December 2013, a Sunni MP named Ahmed al-Alwani was arrested in a raid on his home in Ramadi.', 2013, 12, 30, 2014, 6, 25, 'day', '30 December 2013 – 25 June 2014', 52, 'https://en.wikipedia.org/wiki/Anbar_campaign_(2013%E2%80%932014)'),
  ('Q17144192', 'Islamic State invasion of Iraq', 'In June 2014, the Islamic State of Iraq and the Levant (also known as ISIL or ISIS), which had controlled a large portion of Northeastern Syria at that time during the Syrian civil war, launched a widespread offensive in Iraq, capturing a large swath of territory extending all the way from the Iraq–Syria border to the outskirts of the Iraqi capital city of Baghdad. The offensive came after months of clashes in Anbar province, where tribal groups, and some extremist factions—which had pledged allegiance to ISIL—had been fighting Iraqi government forces in the cities of Fallujah and Ramadi…', 2014, 6, 25, 2014, 6, 25, 'day', '25 June 2014', 59, 'https://en.wikipedia.org/wiki/Islamic_State_invasion_of_Iraq'),
  ('Q17199280', 'Camp Speicher massacre', 'The Camp Speicher massacre was the mass killing of unarmed Shia cadets of the Iraqi Armed Forces by the Islamic State of Iraq and the Levant (ISIL), on 12 June 2014. It occurred in Tikrit, Iraq, which is near the cadets'' military base, Camp Speicher.', 2014, 6, 12, NULL, NULL, NULL, 'day', '12 June 2014', 56, 'https://en.wikipedia.org/wiki/Camp_Speicher_massacre'),
  ('Q17514354', 'Sinjar massacre', 'The Sinjar massacre (Kurdish: Fermana Şingalê or Komkujiya Şingalê) marked the beginning of the genocide of Yazidis by ISIL, the killing and abduction of thousands of Yazidi men, women and children. It took place in August 2014 in Sinjar city and Sinjar District in Iraq''s Nineveh Governorate and was perpetrated by the Islamic State of Iraq and the Levant (ISIL).', 2014, 8, NULL, NULL, NULL, NULL, 'month', 'August 2014', 52, 'https://en.wikipedia.org/wiki/Sinjar_massacre'),
  ('Q17984356', 'Iraqi Civil War of 2014–2017', 'The War in Iraq (2013–2017) also known in Iraq as “حرب داعش" translating to “the war against the Islamic State” was an armed conflict between Iraq and its allies and the Islamic State. Following December 2013, the insurgency escalated into a full-scale war following clashes in parts of western Iraq, which culminated in the Islamic State offensive into Iraq in June 2014, leading to the capture of the cities of Mosul, Tikrit and other cities in western and northern Iraq by the Islamic State.', 2014, 1, 1, 2017, 12, 9, 'day', '1 January 2014 – 9 December 2017', 66, 'https://en.wikipedia.org/wiki/War_in_Iraq_(2013%E2%80%932017)'),
  ('Q21190910', 'Yazidi genocide', 'The Yazidi genocide also known as the 74th firman by Yazidis, was perpetrated by the Islamic State in Iraq and Syria between 2014 and 2017. It was characterized by massacres, genocidal rape, and forced conversions to Islam.', 2014, 8, NULL, NULL, NULL, NULL, 'month', 'August 2014', 61, 'https://en.wikipedia.org/wiki/Yazidi_genocide'),
  ('Q24205448', 'Battle of Fallujah', 'The Third Battle of Fallujah, code-named Operation Breaking Terrorism (Arabic: عملية كسر الإرهاب) by the Iraqi government, was a military operation against ISIL launched to capture the city of Fallujah and its suburbs, located about 69 kilometres (43 mi) west of Baghdad, the capital of Iraq. The operation began on 22 May 2016, three months after the Iraqi forces had started the total siege of Fallujah.', 2016, 6, 29, 2016, 6, 26, 'day', '29 June 2016 – 26 June 2016', 53, 'https://en.wikipedia.org/wiki/Third_Battle_of_Fallujah'),
  ('Q25300887', 'July 2016 Baghdad bombings', 'On 3 July 2016, Islamic State (IS) militants carried out coordinated bomb attacks in Baghdad that killed up to 1,000 civilians and injured hundreds more. A few minutes after midnight local time (2 July, 21:00 UTC), a suicide truck-bomb targeted the mainly Shia district of Karrada, busy with late night shoppers for Ramadan.', 2016, 7, 3, NULL, NULL, NULL, 'day', '3 July 2016', 63, 'https://en.wikipedia.org/wiki/2016_Karrada_bombing'),
  ('Q27429856', 'Battle of Mosul', 'The Battle of Mosul (Arabic: معركة الموصل, Ma''rakat al-Mawṣil) was a major battle initiated by Iraq and allied forces to retake the city of Mosul from the Islamic State (IS), which had seized the city years prior in June 2014. It was the largest conventional land battle in the world since the capture of Baghdad in 2003.', 2016, 10, 16, 2017, 7, 20, 'day', '16 October 2016 – 20 July 2017', 69, 'https://en.wikipedia.org/wiki/Battle_of_Mosul_(2016%E2%80%932017)'),
  ('Q42103453', 'Battle of Kirkuk', 'The Battle of Kirkuk, codenamed Operation Enforcing Security of the 2017 Iraqi–Kurdish conflict, was a military deployment by the Iraqi Security Forces to retake Kirkuk Governorate from the Peshmerga after the latter ignored repeated warnings to withdraw, sparking clashes between the two forces. The advance began on 15 October 2017, with the city of Kirkuk being retaken upon entry of the Iraqi forces as the Kurds fled immediately.', 2017, 10, 15, 2017, 10, 20, 'day', '15 October 2017 – 20 October 2017', 51, 'https://en.wikipedia.org/wiki/Battle_of_Kirkuk_(2017)'),
  ('Q116783960', 'Iraqi Turkmen genocide', 'Persecution of the Iraqi Turkmen by the Islamic State refers to the series of killings, rapes, executions, expulsions, and sexual slavery of the Iraqi Turkmen in Islamic State-controlled territory. The persecution began when IS captured Iraqi Turkmen lands in 2014 and continued until IS lost all of their land in Iraq.', 2017, 8, 31, 2017, 8, 31, 'day', '31 August 2017', 57, 'https://en.wikipedia.org/wiki/Persecution_of_the_Iraqi_Turkmen_by_the_Islamic_State'),
  ('Q72367808', '2019–2021 Iraqi protests', 'A series of demonstrations, marches, sit-ins and civil disobedience took place in Iraq from 2019 until 2021. It started on 1 October 2019, a date which was set by civil activists on social media, spreading mainly over the central and southern provinces of Iraq, to protest corruption, high unemployment, political sectarianism, inefficient public services and foreign interventionism.', 2019, 10, 1, 2021, 12, 5, 'day', '1 October 2019 – 5 December 2021', 59, 'https://en.wikipedia.org/wiki/2019%E2%80%932021_Iraqi_protests'),
  ('Q80438042', '2019–20 attack on the United States embassy in Baghdad', 'On 29 December 2019, the United States conducted airstrikes against Kata''ib Hezbollah''s weapons depots and command centers in Iraq and Syria, reportedly killing at least 25 militiamen and wounding 55 more. The U.S. Department of Defense said the operation was in retaliation for repeated attacks on Iraqi military bases hosting Operation Inherent Resolve (OIR) coalition forces, particularly the 27 December 2019 attack on a Kirkuk airbase that left an American civilian contractor dead.', 2019, 12, 31, 2020, 1, 1, 'day', '31 December 2019 – 1 January 2020', 55, 'https://en.wikipedia.org/wiki/Attack_on_the_United_States_embassy_in_Baghdad'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q80754846', 'assassination of Qasem Soleimani', 'On 3 January 2020, Qasem Soleimani, an Iranian major general, was assassinated by an American drone strike ordered by U.S. president Donald Trump near Baghdad International Airport in Iraq, while travelling to meet Iraqi prime minister Adil Abdul-Mahdi. Soleimani was commander of the Quds Force, one of five branches of Iran''s Islamic Revolutionary Guard Corps (IRGC), which is designated as a terrorist organization by both the United States and European Parliament.', 2020, 1, 3, NULL, NULL, NULL, 'day', '3 January 2020', 70, 'https://en.wikipedia.org/wiki/Assassination_of_Qasem_Soleimani'),
  ('Q81341687', '2020 Iranian attack on U.S. forces in Iraq', 'On 8 January 2020, Iran''s Islamic Revolutionary Guard Corps (IRGC) conducted Operation Martyr Soleimani (Persian: عملیات شهید سلیمانی), launching over 12 ballistic missiles against the United States Armed Forces at al-Asad Airbase in Al Anbar Governorate, Iraq, as well as another airbase in Erbil, in response to the assassination of Major General Qasem Soleimani by a U.S. drone strike. The strike was the largest ballistic missile attack ever against U.S. forces abroad.', 2020, 1, 8, NULL, NULL, NULL, 'day', '8 January 2020', 65, 'https://en.wikipedia.org/wiki/Operation_Martyr_Soleimani'),
  ('Q106615555', 'Baghdad hospital fire', 'On the night of 24 to 25 April 2021, a fire at the Ibn al-Khatib hospital in Baghdad, Iraq, left at least 92 people dead and 110 others injured. The fire was started by the explosion of oxygen tanks designated for COVID-19 patients.', 2021, 4, 24, NULL, NULL, NULL, 'day', '24 April 2021', 55, 'https://en.wikipedia.org/wiki/2021_Baghdad_hospital_fire'),
  ('Q123124528', 'attacks on US bases during the Gaza war', 'Starting on 17 October 2023, and in response to United States support for Israel in the Gaza war, Iran-backed militias initiated a coordinated series of more than 170 attacks on US military bases and assets in Syria, Iraq, and Jordan. These attacks resulted in injuries to dozens of US service members.', 2023, 10, 18, 2024, 2, 4, 'day', '18 October 2023 – 4 February 2024', 51, 'https://en.wikipedia.org/wiki/Attacks_on_US_bases_during_the_Middle_Eastern_crisis_(2023%E2%80%93present)');
